        \coordinate (E) at (6, 2);
    % Vẽ các cạnh của hình thang
    \draw (0,0) -- (4,0) -- (5,2) -- (-1,2) -- cycle;
    \draw (5,2) -- (6,2);
    % Gán nhãn cho các điểm
    \node[above left] at (-1,2) {$M$};
    \node[above right] at (5,2) {$N$};
    \node[below right] at (4,0) {$P$};
    \node[below left] at (0,0) {$Q$};
    % Gán biến x tại góc D
    \node[left] at (0.4,0.2) {$x$};

    % Vẽ đoạn thẳng nối AB
    \draw (-1,2) -- (5,2);
    \draw 
    (5,2) pic[draw,angle radius = 6] {angle = C--B--E} node[shift={(-25:16pt)}]{$ 130^\circ $} 
    (4,0) pic[draw,angle radius = 6] {angle = B--C--D} node[shift={(-45:-15pt)}]{$ 130^\circ $}   
    ;

    \end{tikzpicture}
}
\loigiai{
a) Trên hình vẽ có góc ngoài tại đỉnh $N$ bằng $130^\circ$ và góc $\widehat{NPQ}$ (hay $\widehat{NPM}$ tại góc đáy) bằng $130^\circ$. Hai góc này ở vị trí so le trong bằng nhau nên $MN \parallel PQ$. Suy ra tứ giác $MNPQ$ có một cặp cạnh đối song song nên là hình thang.\\
b) Để hình thang $MNPQ$ là hình thang cân thì hai góc kề một đáy phải bằng nhau: $\widehat{Q} = \widehat{P} = 130^\circ$ (hay $NP$ bằng $x = 130^\circ$, hoặc nếu góc ở đỉnh $D$ kề với đỉnh trên thì bù nhau tuỳ vị trí kí hiệu $x$; theo hình chuẩn $x = 130^\circ$).
}\end{ex}
